lessons.starter_code:
# Decision Making in Python with if-elif-else
student_score = 85

if student_score >= 90:
    grade = "A+ (Distinction)"
elif student_score >= 80:
    grade = "A (Excellent)"
elif student_score >= 70:
    grade = "B (Good)"
elif student_score >= 50:
    grade = "C (Pass)"
else:
    grade = "F (Needs Improvement)"

print(f"Score: {student_score} | Final Grade: {grade}")

